(()=>{
 Object.assign(I18N.en,{historyTitle:'Compare visits',historySubtitle:'Same site. Previous recording and selected visit.'});Object.assign(I18N.ar,{historyTitle:'قارن الزيارات',historySubtitle:'نفس الموضع. التسجيل السابق والزيارة المحددة.'});
 const original=renderHistory;renderHistory=function(){original();if(historyMode!=='demo')return;const data=HistoryDemo.series(historySite),now=data[historyIndex],prev=data[historyIndex-1],pair=el('div','visit-pair'),arabic=lang==='ar';for(const [label,value,date]of [[arabic?'الزيارة السابقة':'Previous visit',prev?prev.value+' Hz':'—',prev?demoDate(prev.date):(arabic?'لا توجد زيارة سابقة':'No earlier visit')],[arabic?'الزيارة المحددة':'Selected visit',now.value+' Hz',demoDate(now.date)],[arabic?'الفرق':'Difference',prev?((now.value-prev.value>=0?'+':'')+(now.value-prev.value)+' Hz'):'—',arabic?'المركز الطيفي • غير تشخيصي':'Spectral centroid • not diagnostic']]){const item=el('div');item.append(el('span',null,label),el('strong',null,value),el('small',null,date));pair.append(item);}document.querySelector('.history-controls').after(pair);};
 function labels(){if(view==='history'){$('pageTitle').textContent=t('historyTitle');$('pageSubtitle').textContent=t('historySubtitle');}}new MutationObserver(labels).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});if(view==='history')renderHistory();labels();
})();
